  id: string;
  name: string;
  buildSlug: string;
  aliasTarget?: string;
  createdAt: Date;
  contextLength: number;
  promptPricePerToken: number;
  completionPricePerToken: number;
  description: string;
  endpointsUrl: string;
};

export type ModelEndpoint = {
  providerName: string;
  contextLength: number;
  maxPromptTokens?: number;
  quantization?: string;
  uptimeLast30m?: number;
};

